import { NextResponse } from 'next/server';
import { AI_MODES, AiError, generateWithFallback, providerStatus } from '@/lib/ai';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

/**
 * GET  -> provider status (safe to call from the browser, never leaks keys).
 * POST -> { text, mode, language, topic } => short notes generated by the AI chain.
 */
export async function GET() {
  const providers = providerStatus();
  return NextResponse.json({
    configured: providers.some((p) => p.configured),
    providers,
  });
}

export async function POST(request: Request) {
  let body: { text?: string; mode?: string; language?: string; topic?: string };
  try {
    body = (await request.json()) as typeof body;
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body.' }, { status: 400 });
  }

  const text = typeof body.text === 'string' ? body.text.trim() : '';
  if (!text) {
    return NextResponse.json({ error: 'Text ya topic khaali hai — kuch to likho.' }, { status: 400 });
  }
  if (text.length > 12000) {
    return NextResponse.json({ error: 'Text 12000 characters se chhota karo.' }, { status: 400 });
  }

  const mode = AI_MODES.includes(body.mode as never) ? (body.mode as (typeof AI_MODES)[number]) : 'short-notes';
  const language = body.language === 'hinglish' ? 'hinglish' : 'en';

  try {
    const result = await generateWithFallback({
      text,
      mode,
      language,
      topic: typeof body.topic === 'string' ? body.topic : undefined,
    });

    return NextResponse.json({
      ok: true,
      mode,
      language,
      notes: result.notes,
      lines: result.lines,
      raw: result.raw,
      provider: result.provider,
      providerLabel: result.providerLabel,
      model: result.model,
      attempts: result.attempts,
      usedFallback: result.usedFallback,
    });
  } catch (error) {
    if (error instanceof AiError) {
      const status = error.code === 'bad_input' ? 400 : 502;
      return NextResponse.json({ error: error.message, code: error.code }, { status });
    }
    console.error('[ai:POST]', error);
    return NextResponse.json(
      { error: 'AI request fail ho gayi. Baad me try karo.' },
      { status: 500 },
    );
  }
}
